import{z as l,x as i,o as B,c as p,q as t,j as A,D as E,d as r,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"LCR 与 NSFR","description":"","frontmatter":{"title":"LCR 与 NSFR","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lcr-nsfr.md","filePath":"econ/lcr-nsfr.md","lastUpdated":1791413859000}'),d={name:"econ/lcr-nsfr.md"};function C(F,a,R,h,S,c){const n=i("Mermaid");return B(),p("div",null,[a[2]||(a[2]=t('<h1 id="lcr-与-nsfr" tabindex="-1">LCR 与 NSFR <a class="header-anchor" href="#lcr-与-nsfr" aria-label="Permalink to &quot;LCR 与 NSFR&quot;">​</a></h1><div class="epigraph"><p>资本回答亏损归谁；流动性覆盖回答三十日内谁能付现。把两个比率写成同一个约束，窗口与股本会再次被混用。</p><footer>—— Basel Committee on Banking Supervision, Basel III: The Liquidity Coverage Ratio, 2013；The Net Stable Funding Ratio, 2014</footer></div><p>定位：<a href="/econ/basel-capital">上一课</a>。风险加权资本与杠杆率已经把损失吸收顺序写成可审计的分子分母。本课缺口是流动性的两道数量阀：覆盖比率（LCR）与净稳定融资比率（NSFR）。不是把 RWA 再讲一遍，也不把 LCR 叫成资本充足。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Diamond–Dybvig 的提取与 Bagehot 的窗口，都发生在资本可能仍为正的时候：资产按持有到期值覆盖负债，但无法在不火灾出售的前提下变成结算资产。巴塞尔资本管的是亏损顺序；若只靠资本，银行仍可以把稳定资金换成隔夜批发，等挤兑来了再去窗口。危机后的流动性标准要把「能撑过压力提取」和「资产与负债的期限别错太远」写成事前比率。</p><p><span class="marginnote">直觉类比：资本回答「亏损了谁先认赔」，流动性回答「今天下午的转账能不能付出去」。一家资本充足率达标、资产总值足够的银行，仍可能死于后者——资产都是三个月后到期的贷款，下午要付的钱一分也变不出来。</span></p><p>缺口是两道不同频率的约束。三十日压力对应挤兑的短期腿；一年稳定融资对应持续的期限转换。BCBS 把它们分开写，正是为了不让一个数字同时充当股本与库存现金。</p><p><span class="marginnote">高流动性资产（HQLA）是压力中仍能按窄折价变现或向央行抵押的资产。它是 Bagehot「好抵押」的事前库存，不是普通股，也不能吸收已经实现的信贷亏损。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LCR：合格 HQLA 的存量，除以指定压力情景下三十日净现金流出，最低为 100%。流出系数按负债类型设定——零售存款低、无保险批发高——把 Diamond–Dybvig 的提取写成监管权重，而不是再解一遍博弈。流入有上限，防止用「假想的贷款回收」把分母做小。</p><p>NSFR：可用稳定资金（资本、长期负债、稳定零售）除以所需稳定资金（按资产流动性与表外加权），最低为 100%，地平线约一年。它惩罚用短批发去持有长而难变现的资产，即使 LCR 在三十日窗口里刚好踩线。</p><p><span class="marginnote">数字实例：HQLA 800 亿、压力下三十日净流出 750 亿，LCR \\(=800/750\\approx 107\\%\\)，踩线达标。不卖任何资产，只把无保险批发换成零售存款，分母降到 500 亿，LCR 跳到 \\(160\\%\\)——负债结构一换，比率大变，这正是流出系数的杠杆。</span></p>',12)),(B(),A(s,null,{default:E(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E8%B5%84%E6%9C%AC%20%2F%20RWA%3A%20%E4%BA%8F%E6%8D%9F%E5%BD%92%E8%B0%81%22%5D%20--%3E%20SOLV%5B%22%E5%81%BF%E4%BB%98%22%5D%0A%20%20LCR%5B%22HQLA%20%2F%2030%E6%97%A5%E5%87%80%E6%B5%81%E5%87%BA%22%5D%20--%3E%20STRESS%5B%22%E5%8E%8B%E5%8A%9B%E6%8F%90%E5%8F%96%22%5D%0A%20%20NSFR%5B%22%E5%8F%AF%E7%94%A8%E7%A8%B3%E5%AE%9A%E8%B5%84%E9%87%91%20%2F%20%E6%89%80%E9%9C%80%E7%A8%B3%E5%AE%9A%E8%B5%84%E9%87%91%22%5D%20--%3E%20MATCH%5B%22%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%22%5D%0A%20%20LCR%20--%3E%20NOTCAP%5B%22%E4%B8%8D%E6%98%AF%E8%B5%84%E6%9C%AC%22%5D%0A%20%20NSFR%20--%3E%20NOTCAP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与内生货币的衔接：盯利率时准备金仍可再供给，HQLA 库存却要求银行在平时持有低收益的结算邻近资产。流动性规则是数量阀，利率规则是价格阀，两者叠在同一张表上。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是把挤兑与期限错配从「事后窗口」改成「事前持有成本」。LCR 提高持有 HQLA 的机会成本，降低对最后贷款人的日常依赖；NSFR 提高短稳长的成本，使期限转换必须由稳定负债来做。两者都不改损失吸收顺序：HQLA 可以按市值波动，亏损仍先记普通股。",-1)),(B(),A(s,null,{default:E(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OW%5B%22%E7%94%A8%E9%9A%94%E5%A4%9C%E6%89%B9%E5%8F%91%E8%B5%84%E9%87%91%E6%BB%9A%E5%8A%A8%E8%9E%8D%E8%B5%84%22%5D%20--%3E%20BUY%5B%22%E4%B9%B0%E5%85%A5%E9%95%BF%E6%9C%9F%E9%9A%BE%E5%8F%98%E7%8E%B0%E8%B5%84%E4%BA%A7%22%5D%0A%20%20BUY%20--%3E%20GAP%5B%22%E8%B4%9F%E5%80%BA%E4%B8%80%E5%A4%A9%E4%B8%80%E7%BB%AD%EF%BC%8C%E8%B5%84%E4%BA%A7%E4%B8%89%E5%B9%B4%E5%9B%9E%E6%AC%BE%22%5D%0A%20%20GAP%20--%3E%20OK%5B%22%E6%9C%AA%E6%9D%A5%2030%20%E6%97%A5%E5%88%B0%E6%9C%9F%E6%B5%81%E5%87%BA%E5%BE%88%E5%B0%91%EF%BC%8CLCR%20%E8%BE%BE%E6%A0%87%22%5D%0A%20%20OW%20--%3E%20RISK%5B%22%E4%BE%9D%E8%B5%96%E5%AF%B9%E6%89%8B%E6%96%B9%E6%98%8E%E5%A4%A9%E7%BB%A7%E7%BB%AD%E5%87%BA%E5%80%9F%22%5D%0A%20%20RISK%20--%3E%20RUN%5B%22%E5%AF%B9%E6%89%8B%E5%81%9C%E6%AD%A2%E7%BB%AD%E5%80%9F%EF%BC%8C%E9%94%99%E9%85%8D%E7%88%86%E9%9B%B7%22%5D%0A%20%20RUN%20--%3E%20NSFR%5B%22NSFR%20%E8%A6%81%E6%B1%82%E4%B8%80%E5%B9%B4%E6%9C%9F%E7%A8%B3%E5%AE%9A%E8%B5%84%E9%87%91%EF%BC%8C%E5%A0%B5%E4%BD%8F%E8%BF%99%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>监管套利的方向换了。资本套利是把风险赶到低权重暴露；流动性套利是把流出赶到低系数负债、把资产赶到被承认为 HQLA 的券。影子银行下一课要问：期限转换能否整体搬出并表银行，从而两比率都管不到。本课先钉：在并表银行内部，流动性与资本是两套会计。</p><h3 id="流出系数不是挤兑概率" tabindex="-1">流出系数不是挤兑概率 <a class="header-anchor" href="#流出系数不是挤兑概率" aria-label="Permalink to &quot;流出系数不是挤兑概率&quot;">​</a></h3><p>零售存款的低流出系数，已经把<a href="/econ/deposit-insurance">存款保险</a>写进 LCR：被保、稳定的存款被当成较少跑。无保险批发的高系数，已经把 TBTF 信念<strong>没有</strong>写成「批发也不会跑」。系数是规则，不是估计出来的挤兑均衡概率。用某次危机的事后提取去反推「LCR 没用」，混淆了规则与模型。</p><p><span class="marginnote">常见误区：把零售流出系数 5% 读成「危机中只有 5% 的储户会取钱」——它是监管设定的保守权重，不是统计估计。权重设多严是委员会的判断；某次挤兑实际跑得更多，不构成对规则的「证伪」，只说明权重该修。</span></p><p><span class="marginnote">NSFR 的「所需稳定资金」对贷款给高权重、对 HQLA 给低权重。它不是风险加权资产：对象是融资期限，不是意外损失。不要把 NSFR 当分母拿去和 CET1 比。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把流动性覆盖叫成资本充足，也不要把资本缓冲叫成三十日库存。窗口在 LCR 之后仍有位置：比率是事前，Bagehot 是压力中的弹性。也不要用 HQLA 的法定名单当 SDF：名单是委员会选择，不是资产定价核。</p><p>本课不写 Pozsar 的实体图谱。下一课<a href="/econ/shadow-banking">影子银行</a>处理跑到两比率外面的期限转换；这里只完成巴塞尔流动性腿。</p><p>后课默认：LCR 管压力提取的库存，NSFR 管稳定融资结构，都不是资本。资本课已经说过这句话，本课把它做成两道可写的比率。套利会把转换推出并表银行。</p><p>三十日与一年是两个频率。踩线 LCR 仍可以靠隔夜批发续一年，所以需要 NSFR。</p><p>HQLA 不能核销贷款亏损。先亏的仍是普通股。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本是损失吸收；LCR / NSFR 是流动性与期限的数量阀。</li><li>LCR：HQLA 对三十日压力净流出；NSFR：稳定资金对所需稳定资金。</li><li>流出系数是规则，不是挤兑博弈的解。</li><li>出处：BCBS, LCR 2013；NSFR 2014；对照 Basel III 框架。</li></ul>',13))])}const m=l(d,[["render",C]]);export{L as __pageData,m as default};
